12	        if (vertexCount < 0) {
13	            throw new IllegalArgumentException("Vertex count cannot be negative.");
14	        }
15	
16	        adjacencyList = new ArrayList<>(vertexCount);
17	        adjacencyViews = new ArrayList<>(vertexCount);
18	        for (int vertex = 0; vertex < vertexCount; vertex++) {
